


/** One thing a buyer can do with an order, subscription, invoice or return they read through /v1/me. Show the actions with is_required as what needs the buyer's attention, and the first available action as the primary action on the resource's page in your account. */ export type BuyerActionInput = { /** When the buyer needs to act by. Omitted when the action has no deadline, or when the resource's state or the store's policy doesn't allow it. Format: date-time. */ "due_at"?: string | globalThis.Date; /** Whether this session can take the action now. */ "is_available": boolean; /** Whether the store needs the buyer to take the action, such as paying a due invoice. It stays true when the only thing in the way is signing in. */ "is_required": boolean; /** What the action is. Each resource lists its own kinds in a fixed order. New kinds may be added; ignore kinds you don't recognize. */ "kind": "start_return" | "resend_receipt" | "cancel" | "pause" | "resume" | "reactivate" | "update_payment_method" | "pay" | "withdraw" | "ship_items" | "pay_balance" | "retry_payment" | "update_delivery" | "skip" | "update_billing_interval" | "update_quantity" | "swap_items" | "renew"; /** Why the action can't be taken now. Present exactly when is_available is false. New reasons may be added; show a general message for a reason you don't recognize. */ "unavailable_reason"?: "sign_in_required" | "store_policy" | "not_in_state" | "window_closed" | "nothing_to_return" | "collection_unavailable" | "limit_reached"; };
